-- === Application Launchers ===
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.bind("SUPER + Q", hl.dsp.exec_cmd("kitty"))
hl.bind("SUPER + Space", hl.dsp.exec_cmd("dms ipc call spotlight toggle"))
hl.bind("SUPER + V", hl.dsp.exec_cmd("dms ipc call clipboard toggle"))
hl.bind("SUPER + X", hl.dsp.exec_cmd("dms ipc call processlist focusOrToggle"))
hl.bind("SUPER + I", hl.dsp.exec_cmd("dms ipc call settings focusOrToggle"))
hl.bind("SUPER + N", hl.dsp.exec_cmd("dms ipc call notifications toggle"))
hl.bind("SUPER + SHIFT + N", hl.dsp.exec_cmd("dms ipc call notepad toggle"))
hl.bind("SUPER + Y", hl.dsp.exec_cmd("dms ipc call dankdash wallpaper"))
hl.bind("SUPER + TAB", hl.dsp.exec_cmd("dms ipc call hypr toggleOverview"))
hl.bind("SUPER + P", hl.dsp.exec_cmd("kitty --title Hypr-Monitors-TUI-2_floating monitui"))

-- === Cheat sheet
hl.bind("SUPER + SHIFT + Slash", hl.dsp.exec_cmd("dms ipc call keybinds toggle hyprland"))

-- === Security ===
hl.bind("SUPER + L", hl.dsp.exec_cmd("dms ipc call lock lock"))
hl.bind("SUPER + CTRL + M", hl.dsp.exit())
hl.bind("CTRL + ALT + Delete", hl.dsp.exec_cmd("dms ipc call powermenu toggle"))

-- === Audio Controls ===
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("dms ipc call audio increment 3"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("dms ipc call audio decrement 3"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("dms ipc call audio mute"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("dms ipc call audio micmute"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("dms ipc call mpris playPause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("dms ipc call mpris playPause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("dms ipc call mpris previous"), { locked = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("dms ipc call mpris next"), { locked = true })
hl.bind("CTRL + XF86AudioRaiseVolume", hl.dsp.exec_cmd("dms ipc call mpris increment 3"), { locked = true, repeating = true })
hl.bind("CTRL + XF86AudioLowerVolume", hl.dsp.exec_cmd("dms ipc call mpris decrement 3"), { locked = true, repeating = true })

-- === Brightness Controls ===
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("dms ipc call brightness increment 5 \"\""), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("dms ipc call brightness decrement 5 \"\""), { locked = true, repeating = true })
-- externals only
hl.bind("CTRL + code:232", hl.dsp.exec_cmd("ddcutil setvcp 10 - 10"))
hl.bind("CTRL + code:233", hl.dsp.exec_cmd("ddcutil setvcp 10 + 10"))

-- === Window Management ===
hl.bind("SUPER + C", hl.dsp.window.close())
hl.bind("SUPER + F", hl.dsp.window.float({ action = "toggle" }))
-- bind = SUPER SHIFT, F, fullscreen, 0
hl.bind("ALT + code:36", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
-- bind = SUPER SHIFT, T, togglefloating
hl.bind("SUPER + G", hl.dsp.group.toggle())
hl.bind("SUPER + ALT + right", hl.dsp.group.next())
hl.bind("SUPER + ALT + left", hl.dsp.group.prev())
-- bind = SUPER SHIFT, W, exec, dms ipc call window-rules toggle

-- === Focus Navigation ===
hl.bind("ALT + tab", hl.dsp.window.cycle_next({ next = true }))
hl.bind("ALT + SHIFT + tab", hl.dsp.window.cycle_next({ prev = true }))
hl.bind("SUPER + left", hl.dsp.focus({ direction = "left" }))
hl.bind("SUPER + down", hl.dsp.focus({ direction = "down" }))
hl.bind("SUPER + up", hl.dsp.focus({ direction = "up" }))
hl.bind("SUPER + right", hl.dsp.focus({ direction = "right" }))
-- bind = SUPER, H, movefocus, l
-- bind = SUPER, J, movefocus, d
-- bind = SUPER, K, movefocus, u
-- bind = SUPER, L, movefocus, r

-- === Window Movement ===
hl.bind("SUPER + CTRL + left", hl.dsp.window.move({ into_or_create_group = "l" }))
hl.bind("SUPER + CTRL + down", hl.dsp.window.move({ into_or_create_group = "d" }))
hl.bind("SUPER + CTRL + up", hl.dsp.window.move({ into_or_create_group = "u" }))
hl.bind("SUPER + CTRL + right", hl.dsp.window.move({ into_or_create_group = "r" }))
-- bind = SUPER CTRL, H, movewindoworgroup, l
-- bind = SUPER CTRL, J, movewindoworgroup, d
-- bind = SUPER CTRL, K, movewindoworgroup, u
-- bind = SUPER CTRL, L, movewindoworgroup, r

-- === Resize Windows ===
hl.bind("SUPER + SHIFT + right", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = math.floor(w.size.x * 20 / 100), y = 0, relative = true })) end)
hl.bind("SUPER + SHIFT + left", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = math.floor(w.size.x * -20 / 100), y = 0, relative = true })) end)
hl.bind("SUPER + SHIFT + up", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = 0, y = math.floor(w.size.y * -20 / 100), relative = true })) end)
hl.bind("SUPER + SHIFT + down", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = 0, y = math.floor(w.size.y * 20 / 100), relative = true })) end)

-- === Column Navigation ===
