-- bind = SUPER, End, focuswindow, last

-- === Monitor Navigation ===
hl.bind("SUPER + CTRL + 1", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = 0 })) end)
hl.bind("SUPER + CTRL + 2", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = 1 })) end)
hl.bind("SUPER + CTRL + 3", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = 2 })) end)
hl.bind("SUPER + CTRL + 4", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = 3 })) end)
